/**
 * Vite exposes only variables prefixed with VITE_ to client-side code via
 * import.meta.env. Variables are statically replaced at build time, so the
 * string value is inlined into the bundle – they are never sent to the browser
 * at runtime as process.env values would be in Node.
 *
 * Expected .env entry:
 *   VITE_API_BASE_URL=https://api.example.com
 */

const API_BASE_URL: string = (() => {
  const url = import.meta.env.VITE_API_BASE_URL;

  if (!url) {
    throw new Error(
      'VITE_API_BASE_URL is not defined. ' +
        'Add it to your .env file and restart the dev server.',
    );
  }

  // Normalise: strip a trailing slash so callers can always write "/path".
  return url.replace(/\/$/, '');
})();

// ---------------------------------------------------------------------------
// Types
