export type HttpMethod = 'GET' | 'POST' | 'PUT' | 'PATCH' | 'DELETE';

export interface ApiRequestOptions extends Omit<RequestInit, 'method' | 'body'> {
  method?: HttpMethod;
  /** Automatically JSON-serialised and sent with Content-Type: application/json. */
  body?: unknown;
  /** Query-string parameters appended to the URL. */
  params?: Record<string, string | number | boolean | undefined>;
}

export interface ApiError extends Error {
  status: number;
  data: unknown;
}

// ---------------------------------------------------------------------------
// Error helper
// ---------------------------------------------------------------------------

function createApiError(status: number, data: unknown, message: string): ApiError {
  const error = new Error(message) as ApiError;
  error.name = 'ApiError';
  error.status = status;
  error.data = data;
  return error;
}

// ---------------------------------------------------------------------------
// Core fetch wrapper
