/**
 * Sends an HTTP request to `API_BASE_URL + path`.
 *
 * - Automatically serialises / deserialises JSON.
 * - Throws an `ApiError` for non-2xx responses so callers never need to check
 *   `response.ok` manually.
 *
 * @example
 * const user = await apiFetch<User>('/users/1');
 * const created = await apiFetch<User>('/users', { method: 'POST', body: { name: 'Alice' } });
 */
export async function apiFetch<T = unknown>(
  path: string,
  { method = 'GET', body, params, headers, ...rest }: ApiRequestOptions = {},
): Promise<T> {
  // Build URL -----------------------------------------------------------------
  const url = new URL(`${API_BASE_URL}${path}`);

  if (params) {
    Object.entries(params).forEach(([key, value]) => {
      if (value !== undefined) {
        url.searchParams.set(key, String(value));
      }
    });
  }

  // Build headers -------------------------------------------------------------
  const resolvedHeaders = new Headers(headers as HeadersInit | undefined);

  if (body !== undefined && !resolvedHeaders.has('Content-Type')) {
    resolvedHeaders.set('Content-Type', 'application/json');
  }

  // Send request --------------------------------------------------------------
  const response = await fetch(url.toString(), {
    method,
    headers: resolvedHeaders,
    body: body !== undefined ? JSON.stringify(body) : undefined,
    ...rest,
  });

  // Parse response body -------------------------------------------------------
  const contentType = response.headers.get('Content-Type') ?? '';
  const isJson = contentType.includes('application/json');
  const data: unknown = isJson ? await response.json() : await response.text();

  if (!response.ok) {
    throw createApiError(
      response.status,
      data,
      `API error ${response.status} on ${method} ${url.toString()}`,
    );
  }

  return data as T;
}
