/**
 * Vite exposes variables prefixed with VITE_ via import.meta.env.
 * They are statically replaced at build time, so no runtime process.env access is needed.
 *
 * Required .env entry:
 *   VITE_API_BASE_URL=https://api.example.com
 */

/** Shape of the options accepted by the fetch helper. */
export interface ApiRequestOptions extends Omit<RequestInit, 'body'> {
  /** Typed request body – will be serialised to JSON automatically. */
  body?: unknown;
}

/** A successful API response envelope. */
export interface ApiResponse<T = unknown> {
  data: T;
  status: number;
  headers: Headers;
}

// ---------------------------------------------------------------------------
// Read + validate the environment variable
// ---------------------------------------------------------------------------

function resolveBaseUrl(): string {
  const raw = import.meta.env.VITE_API_BASE_URL;

  if (!raw || typeof raw !== 'string') {
    throw new Error(
      '[api/client] VITE_API_BASE_URL is not defined. ' +
        'Add it to your .env file and restart the dev server.',
    );
  }

  // Strip a trailing slash so callers can always write '/resource' paths.
  return raw.replace(/\/$/, '');
}

const BASE_URL: string = resolveBaseUrl();

// ---------------------------------------------------------------------------
// Core fetch helper
// ---------------------------------------------------------------------------

/**
 * Thin wrapper around `fetch` that:
 *   - Prefixes every request with the configured base URL
 *   - Serialises plain-object bodies to JSON and sets Content-Type
 *   - Throws a descriptive error for non-2xx responses
 *   - Returns typed response data
 */
export async function apiFetch<T = unknown>(
  path: string,
  { body, headers: extraHeaders, ...rest }: ApiRequestOptions = {},
): Promise<ApiResponse<T>> {
  // Normalise path so double-slashes never appear in the URL.
  const url = `${BASE_URL}/${path.replace(/^\//, '')}`;

  const isJsonBody = body !== undefined && body !== null;

  const headers = new Headers(extraHeaders);
  if (isJsonBody && !headers.has('Content-Type')) {
    headers.set('Content-Type', 'application/json');
  }

  const response = await fetch(url, {
    ...rest,
    headers,
    body: isJsonBody ? JSON.stringify(body) : undefined,
  });

  if (!response.ok) {
    const text = await response.text().catch(() => '(no body)');
    throw new Error(
      `[api/client] ${rest.method ?? 'GET'} ${url} → ${response.status} ${response.statusText}: ${text}`,
    );
  }

  // Gracefully handle 204 No Content (and similar bodyless responses).
  const data: T =
    response.status === 204
      ? (undefined as unknown as T)
      : await response.json();

  return { data, status: response.status, headers: response.headers };
}

// ---------------------------------------------------------------------------
// Convenience wrappers
// ---------------------------------------------------------------------------

export const api = {
  get: <T = unknown>(path: string, options?: Omit<ApiRequestOptions, 'body'>) =>
    apiFetch<T>(path, { ...options, method: 'GET' }),

  post: <T = unknown>(path: string, body?: unknown, options?: ApiRequestOptions) =>
    apiFetch<T>(path, { ...options, method: 'POST', body }),

  put: <T = unknown>(path: string, body?: unknown, options?: ApiRequestOptions) =>
    apiFetch<T>(path, { ...options, method: 'PUT', body }),

  patch: <T = unknown>(path: string, body?: unknown, options?: ApiRequestOptions) =>
    apiFetch<T>(path, { ...options, method: 'PATCH', body }),

  delete: <T = unknown>(path: string, options?: ApiRequestOptions) =>
    apiFetch<T>(path, { ...options, method: 'DELETE' }),
} as const;
