  timeout = 30_000,
): Promise<ApiResponse<T>> {
  const url = `${apiBaseUrl}${path.startsWith('/') ? path : `/${path}`}`;

  const controller = new AbortController();
  const timerId = setTimeout(() => controller.abort(), timeout);

  const token = getAuthToken(); // see below

  const defaultHeaders: HeadersInit = {
    'Content-Type': 'application/json',
    ...(token ? { Authorization: `Bearer ${token}` } : {}),
  };

  let response: Response;

  try {
    response = await fetch(url, {
      ...init,
      headers: {
        ...defaultHeaders,
        ...init.headers, // caller headers win
      },
      signal: controller.signal,
    });
  } catch (err) {
    if ((err as DOMException).name === 'AbortError') {
      throw new Error(`[api] Request timed out after ${timeout} ms: ${url}`);
    }
    throw err;
  } finally {
    clearTimeout(timerId);
  }

  if (!response.ok) {
    const body = await response.text().catch(() => '');
    throw new Error(
      `[api] HTTP ${response.status} ${response.statusText} – ${url}\n${body}`,
    );
  }

  // Return empty object for 204 No Content
  const data: T =
    response.status === 204 ? ({} as T) : ((await response.json()) as T);

  return { status: response.status, data };
}

