): Promise<T> {
  // Normalise the path so callers can write '/users' or 'users' interchangeably.
  const url = `${apiBaseUrl.replace(/\/$/, '')}/${path.replace(/^\//, '')}`;

  const isJsonBody = body !== undefined && body !== null;

  const headers = new Headers(extraHeaders);
  if (isJsonBody && !headers.has('Content-Type')) {
    headers.set('Content-Type', 'application/json');
  }

  const response = await fetch(url, {
    ...rest,
    headers,
    body: isJsonBody ? JSON.stringify(body) : undefined,
  });

  if (!response.ok) {
    // Attempt to surface a message from the response body.
    let detail = response.statusText;
    try {
      const json = (await response.json()) as { message?: string; error?: string };
      detail = json.message ?? json.error ?? detail;
    } catch {
      // Response was not JSON – keep the statusText fallback.
