```typescript
/**
 * Typed augmentation for Vite's ImportMetaEnv so TypeScript knows about
 * our custom VITE_ variables at compile time.
 *
 * Place this in a .d.ts file (e.g. src/vite-env.d.ts) or inline here.
 */
interface ImportMetaEnv {
  readonly VITE_API_BASE_URL: string;
  // Add further VITE_ variables here as the app grows.
}

interface ImportMeta {
  readonly env: ImportMetaEnv;
}

// ---------------------------------------------------------------------------
// Read the variable at module-initialisation time.
// Vite statically replaces `import.meta.env.VITE_*` at build time, so the
// value is baked in — no runtime environment object is involved.
// ---------------------------------------------------------------------------
const apiBaseUrl = import.meta.env.VITE_API_BASE_URL;

if (!apiBaseUrl) {
  throw new Error(
    'VITE_API_BASE_URL is not defined. ' +
      'Add it to your .env file (e.g. VITE_API_BASE_URL=http://localhost:7007).',
  );
}

// Strip a trailing slash once so every call-site can safely write `/path`.
const normalizedBase = apiBaseUrl.replace(/\/$/, '');

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

export type ApiRequestInit = Omit<RequestInit, 'body'> & {
  /** Automatically JSON-serialised and sets Content-Type when provided. */
  json?: unknown;
};

export interface ApiResponse<T> {
  data: T;
  status: number;
  headers: Headers;
}

// ---------------------------------------------------------------------------
// Core helper
// ---------------------------------------------------------------------------

/**
 * Thin fetch wrapper that:
 *  - Prepends the configured API base URL.
 *  - Serialises a `json` body and sets the correct Content-Type header.
 *  - Deserialises the JSON response body.
 *  - Throws a descriptive error for non-2xx responses.
 *
 * @example
 * const { data } = await apiFetch<Catalog>('/api/catalog/entities');
 */
export async function apiFetch<T = unknown>(
  path: string,
  { json, headers: extraHeaders, ...init }: ApiRequestInit = {},
): Promise<ApiResponse<T>> {
  const url = `${normalizedBase}${path}`;

  const headers = new Headers(extraHeaders);

  let body: BodyInit | undefined;
  if (json !== undefined) {
    body = JSON.stringify(json);
    headers.set('Content-Type', 'application/json');
  }

  const response = await fetch(url, { ...init, headers, body });

  if (!response.ok) {
    // Attempt to surface a server-provided error message.
    const text = await response.text().catch(() => '');
    throw new Error(
      `API request failed [${response.status} ${response.statusText}] ${url}` +
        (text ? `\n${text}` : ''),
    );
  }

  // Return an empty object for 204 No Content so callers always get `data`.
  const data: T =
    response.status === 204 ? ({} as T) : ((await response.json()) as T);

  return { data, status: response.status, headers: response.headers };
}

// ---------------------------------------------------------------------------
// Convenience shorthands
// ---------------------------------------------------------------------------

/** GET  */
export const apiGet = <T>(path: string, init?: ApiRequestInit) =>
  apiFetch<T>(path, { method: 'GET', ...init });

/** POST with a JSON body */
export const apiPost = <T>(path: string, json: unknown, init?: ApiRequestInit) =>
  apiFetch<T>(path, { method: 'POST', json, ...init });

/** PUT with a JSON body */
export const apiPut = <T>(path: string, json: unknown, init?: ApiRequestInit) =>
  apiFetch<T>(path, { method: 'PUT', json, ...init });

/** DELETE */
export const apiDelete = <T>(path: string, init?: ApiRequestInit) =>
  apiFetch<T>(path, { method: 'DELETE', ...init });
```

