const API_BASE_URL = import.meta.env.VITE_API_BASE_URL;

if (!API_BASE_URL) {
  throw new Error(
    '[apiClient] VITE_API_BASE_URL is not set. ' +
      'Add it to your .env file, e.g.:\n' +
      '  VITE_API_BASE_URL=http://localhost:7007',
  );
}

/** Subset of fetch options we want callers to control. */
export type ApiRequestInit = Omit<RequestInit, 'body'> & {
  /** Automatically JSON-serialised and sent with Content-Type: application/json. */
  body?: unknown;
};

/** Shape returned by every helper call. */
export interface ApiResponse<T = unknown> {
  status: number;
  data: T;
}

/**
 * Thin fetch wrapper that:
 *  - Prefixes every request with VITE_API_BASE_URL
 *  - Serialises plain-object bodies to JSON
 *  - Deserialises JSON responses
 *  - Throws a descriptive error for non-2xx responses
 */
export async function apiFetch<T = unknown>(
  path: string,
  { body, headers, ...rest }: ApiRequestInit = {},
): Promise<ApiResponse<T>> {
  const url = `${API_BASE_URL}${path.startsWith('/') ? path : `/${path}`}`;

  const resolvedHeaders = new Headers(headers);

  let serialisedBody: BodyInit | undefined;
  if (body !== undefined) {
    serialisedBody = JSON.stringify(body);
    if (!resolvedHeaders.has('Content-Type')) {
      resolvedHeaders.set('Content-Type', 'application/json');
    }
  }

  const response = await fetch(url, {
    ...rest,
    headers: resolvedHeaders,
    body: serialisedBody,
  });

  // Always attempt to parse JSON; fall back to null so callers still get a
  // structured response even for 204 No Content etc.
  const data: T = response.headers
    .get('Content-Type')
    ?.includes('application/json')
    ? await response.json()
    : null;

  if (!response.ok) {
    throw new Error(
      `[apiClient] ${rest.method ?? 'GET'} ${url} failed — ` +
        `HTTP ${response.status} ${response.statusText}`,
    );
  }

  return { status: response.status, data };
}
