/**
 * Typed augmentation for Vite's ImportMetaEnv so TypeScript knows about our
 * custom variable.  Place this block in a dedicated `src/vite-env.d.ts` file
 * (or any `.d.ts` file included by your tsconfig) in real projects.
 */
interface ImportMetaEnv {
  readonly VITE_API_BASE_URL: string;
}

// Narrows the global ImportMeta type so import.meta.env is fully typed.
interface ImportMeta {
  readonly env: ImportMetaEnv;
}

// ---------------------------------------------------------------------------
// Read the env variable at module-initialisation time.
// Vite statically replaces `import.meta.env.VITE_*` expressions at build time,
// so this is safe for both development and production bundles.
// ---------------------------------------------------------------------------
const apiBaseUrl = import.meta.env.VITE_API_BASE_URL;

if (!apiBaseUrl) {
  throw new Error(
    'VITE_API_BASE_URL is not defined. ' +
      'Add it to your .env file as VITE_API_BASE_URL=https://your-api.example.com',
  );
}

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

export type HttpMethod = 'GET' | 'POST' | 'PUT' | 'PATCH' | 'DELETE';

export interface RequestOptions extends Omit<RequestInit, 'method' | 'body'> {
  method?: HttpMethod;
  /** Automatically JSON-serialised and sent as `application/json`. */
  body?: unknown;
}

export interface ApiError extends Error {
  status: number;
  url: string;
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

function buildApiError(message: string, status: number, url: string): ApiError {
  const error = new Error(message) as ApiError;
  error.name = 'ApiError';
  error.status = status;
  error.url = url;
  return error;
}

// ---------------------------------------------------------------------------
// Core fetch wrapper
// ---------------------------------------------------------------------------

/**
 * Sends an authenticated request to the configured API and returns the
 * deserialised JSON body typed as `T`.
 *
 * @example
 * const user = await apiFetch<User>('/users/me');
 * const created = await apiFetch<Catalog>('/catalogs', { method: 'POST', body: payload });
 */
export async function apiFetch<T>(
  path: string,
  options: RequestOptions = {},
): Promise<T> {
  const { method = 'GET', body, headers: extraHeaders, ...rest } = options;

  // Normalise the path so callers may or may not include a leading slash.
  const url = `${apiBaseUrl.replace(/\/$/, '')}/${path.replace(/^\//, '')}`;

  const headers = new Headers(extraHeaders as HeadersInit | undefined);

  let serialisedBody: BodyInit | undefined;
  if (body !== undefined) {
    serialisedBody = JSON.stringify(body);
    if (!headers.has('Content-Type')) {
      headers.set('Content-Type', 'application/json');
    }
  }

  const response = await fetch(url, {
    method,
    headers,
    body: serialisedBody,
    ...rest,
  });

  if (!response.ok) {
    const message = `API request failed: ${method} ${url} → ${response.status} ${response.statusText}`;
    throw buildApiError(message, response.status, url);
  }

  // 204 No Content and similar responses carry no body.
  if (response.status === 204 || response.headers.get('Content-Length') === '0') {
    return undefined as T;
  }

  return response.json() as Promise<T>;
}
