  path: string,
  { body, headers, ...rest }: ApiRequestInit = {},
): Promise<ApiResponse<T>> {
  const url = `${API_BASE_URL.replace(/\/$/, '')}/${path.replace(/^\//, '')}`;

  const hasBody = body !== undefined;

  const response = await fetch(url, {
    ...rest,
    body: hasBody ? JSON.stringify(body) : undefined,
