// src/lib/apiClient.ts

/**
 * Read the API base URL from a Vite environment variable.
 *
 * VITE_ prefix is required for Vite to expose the variable to client-side
 * source code. Vite statically replaces `import.meta.env.VITE_*` references
 * at build time — process.env is NOT available in Vite client code.
 *
 * Set the variable in your .env file:
 *   VITE_API_BASE_URL=https://api.example.com
 */
const API_BASE_URL: string = import.meta.env.VITE_API_BASE_URL;

if (!API_BASE_URL) {
  throw new Error(
    'Missing required environment variable: VITE_API_BASE_URL\n' +
      'Add it to your .env file: VITE_API_BASE_URL=https://api.example.com',
  );
}

/** Options accepted by the fetch helper, minus the body (handled separately). */
export interface ApiRequestOptions extends Omit<RequestInit, 'body'> {
  body?: unknown;
}

/** A structured error that carries the HTTP status alongside the message. */
export class ApiError extends Error {
  constructor(
    public readonly status: number,
    message: string,
  ) {
    super(message);
    this.name = 'ApiError';
  }
}

/**
 * Thin fetch wrapper pre-configured with the API base URL.
 *
 * - Automatically serialises plain-object bodies to JSON and sets the
 *   Content-Type header accordingly.
 * - Throws an `ApiError` for any non-2xx response so callers never have to
 *   inspect `response.ok` themselves.
 * - Returns the parsed JSON body typed as `T`.
 *
 * @example
 * const user = await apiFetch<User>('/users/1');
 * const created = await apiFetch<User>('/users', { method: 'POST', body: { name: 'Alice' } });
 */
export async function apiFetch<T>(
  path: string,
  { body, headers, ...rest }: ApiRequestOptions = {},
): Promise<T> {
  const url = `${API_BASE_URL}${path}`;

  const isJsonBody = body !== undefined && typeof body === 'object';

  const response = await fetch(url, {
    ...rest,
    headers: {
      'Content-Type': 'application/json',
      Accept: 'application/json',
      ...headers,
    },
    body: isJsonBody ? JSON.stringify(body) : (body as BodyInit | undefined),
  });

  if (!response.ok) {
    const text = await response.text().catch(() => response.statusText);
    throw new ApiError(response.status, `API error ${response.status}: ${text}`);
  }

  // 204 No Content — nothing to parse.
  if (response.status === 204) {
    return undefined as T;
  }

  return response.json() as Promise<T>;
}
