/**
 * Typed augmentation for Vite's ImportMeta so TypeScript knows about our
 * custom VITE_ variables. Place this in a `vite-env.d.ts` (or any *.d.ts
 * file included by your tsconfig) to get full type safety everywhere.
 *
 * /// <reference types="vite/client" />
 *
 * interface ImportMetaEnv {
 *   readonly VITE_API_BASE_URL: string;
 * }
 *
 * interface ImportMeta {
 *   readonly env: ImportMetaEnv;
 * }
 */

// ---------------------------------------------------------------------------
// 1. Read the environment variable via import.meta.env (Vite-idiomatic).
//    Vite statically replaces these at build time — process.env is NOT used.
// ---------------------------------------------------------------------------
const apiBaseUrl: string = import.meta.env.VITE_API_BASE_URL;

if (!apiBaseUrl) {
  // Fail fast during development; a missing base URL means every request
  // will silently go to the wrong place.
  throw new Error(
    '[api/client] VITE_API_BASE_URL is not defined. ' +
      'Add it to your .env file: VITE_API_BASE_URL=https://example.com/api',
  );
}

// ---------------------------------------------------------------------------
// 2. Shared request defaults.
// ---------------------------------------------------------------------------
const DEFAULT_HEADERS: HeadersInit = {
  'Content-Type': 'application/json',
};

// ---------------------------------------------------------------------------
// 3. Typed helper types.
// ---------------------------------------------------------------------------
export type HttpMethod = 'GET' | 'POST' | 'PUT' | 'PATCH' | 'DELETE';

export interface RequestOptions extends Omit<RequestInit, 'method' | 'body'> {
  /** Query-string parameters appended to the URL. */
  params?: Record<string, string | number | boolean>;
  /** Request body — serialised to JSON automatically. */
  body?: unknown;
}

export interface ApiResponse<T> {
  data: T;
  status: number;
  headers: Headers;
}

// ---------------------------------------------------------------------------
// 4. Core fetch helper.
// ---------------------------------------------------------------------------

/**
 * Sends an HTTP request to `apiBaseUrl/<path>` and returns the parsed JSON
 * response wrapped in an {@link ApiResponse}.
 *
 * @example
 * const { data } = await apiFetch<Catalog>('GET', '/catalog/entities');
 */
export async function apiFetch<T>(
  method: HttpMethod,
  path: string,
  { params, body, headers, ...rest }: RequestOptions = {},
): Promise<ApiResponse<T>> {
  // Build URL, appending any query parameters.
  const url = new URL(
    // Normalise slashes so callers can write '/entities' or 'entities'.
    `${apiBaseUrl.replace(/\/$/, '')}/${path.replace(/^\//, '')}`,
  );

  if (params) {
    for (const [key, value] of Object.entries(params)) {
      url.searchParams.set(key, String(value));
    }
  }

  const response = await fetch(url.toString(), {
    method,
    headers: { ...DEFAULT_HEADERS, ...headers },
    // Only attach a body for methods that allow one.
    body:
      body !== undefined && method !== 'GET' && method !== 'DELETE'
        ? JSON.stringify(body)
        : undefined,
    ...rest,
  });

  if (!response.ok) {
    throw new ApiError(response.status, response.statusText, await response.text());
  }

  // Gracefully handle 204 No Content (no body to parse).
  const data: T =
    response.status === 204 ? (undefined as unknown as T) : await response.json();

  return { data, status: response.status, headers: response.headers };
