 * Typed augmentation for Vite's import.meta.env so TypeScript knows about
 * our custom variable. Place this in a *.d.ts file (e.g. src/vite-env.d.ts)
 * or inline here for illustration purposes.
 */
interface ImportMetaEnv {
  readonly VITE_API_BASE_URL: string;
  // add further VITE_* variables here as your app grows
}

