  throw new Error(
    '[apiClient] VITE_API_BASE_URL is not defined. ' +
      'Add it to your .env file and prefix it with VITE_.',
  );
}

/** Options accepted by every request helper, extending native RequestInit. */
export interface ApiRequestOptions extends Omit<RequestInit, 'body'> {
  /** Typed request body — will be JSON-serialised automatically. */
  body?: unknown;
}

/** A successful API response envelope. */
export interface ApiResponse<T> {
  data: T;
  status: number;
}

/**
 * Thin fetch wrapper pre-configured with the API base URL.
 *
 * - Automatically sets `Content-Type: application/json` when a body is present.
 * - Deserialises the response as JSON.
 * - Throws a descriptive error for non-2xx responses.
 *
 * @example
 * const { data } = await apiFetch<User[]>('/users');
 * const { data: created } = await apiFetch<User>('/users', {
 *   method: 'POST',
 *   body: { name: 'Alice' },
 * });
 */
export async function apiFetch<T>(
  path: string,
  { body, headers, ...rest }: ApiRequestOptions = {},
): Promise<ApiResponse<T>> {
  const url = `${API_BASE_URL}${path}`;

  const serialisedBody = body !== undefined ? JSON.stringify(body) : undefined;

  const mergedHeaders = new Headers(headers);
  if (serialisedBody !== undefined && !mergedHeaders.has('Content-Type')) {
    mergedHeaders.set('Content-Type', 'application/json');
  }

  const response = await fetch(url, {
    body: serialisedBody,
    headers: mergedHeaders,
    ...rest,
  });

  if (!response.ok) {
    const text = await response.text().catch(() => '');
    throw new Error(
      `[apiClient] ${rest.method ?? 'GET'} ${url} failed — ` +
        `HTTP ${response.status} ${response.statusText}` +
        (text ? `: ${text}` : ''),
    );
  }

  const data: T = await response.json();
  return { data, status: response.status };
}
