/**
 * Reads the API base URL from the Vite environment.
 *
 * The variable must be defined in your .env file (or CI environment) as:
 *   VITE_API_BASE_URL=https://api.example.com
 *
 * Vite statically replaces `import.meta.env.*` references at build time.
 * Never use `process.env` here — it is not available in Vite client code.
 */
const API_BASE_URL: string = import.meta.env.VITE_API_BASE_URL;

if (!API_BASE_URL) {
  throw new Error(
    'VITE_API_BASE_URL is not defined. ' +
      'Add it to your .env file or deployment environment.',
  );
}

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

export type HttpMethod = 'GET' | 'POST' | 'PUT' | 'PATCH' | 'DELETE';

export interface ApiRequestInit extends Omit<RequestInit, 'method' | 'body'> {
  method?: HttpMethod;
  /** Automatically serialised to JSON and sets Content-Type when provided. */
  json?: unknown;
}

export interface ApiResponse<T = unknown> {
  data: T;
  status: number;
  headers: Headers;
}

// ---------------------------------------------------------------------------
// Core helper
// ---------------------------------------------------------------------------

/**
 * Thin fetch wrapper that:
 *  - Prepends the configured base URL to every request path.
 *  - Serialises `json` payloads and sets the correct Content-Type header.
 *  - Throws a descriptive error for non-2xx responses.
 *  - Returns a typed `ApiResponse<T>` so callers keep full control.
 *
 * @example
 * const { data } = await apiFetch<Catalog>('/api/catalog/entities');
 *
 * @example
 * const { data } = await apiFetch<Entity>('/api/catalog/entities', {
 *   method: 'POST',
 *   json: { kind: 'Component', metadata: { name: 'my-service' } },
 * });
 */
export async function apiFetch<T = unknown>(
  path: string,
  { json, headers: extraHeaders, method = 'GET', ...rest }: ApiRequestInit = {},
): Promise<ApiResponse<T>> {
  const url = `${API_BASE_URL.replace(/\/$/, '')}/${path.replace(/^\//, '')}`;

  const headers = new Headers(extraHeaders);

  let body: BodyInit | undefined;
  if (json !== undefined) {
    body = JSON.stringify(json);
    headers.set('Content-Type', 'application/json');
  }

  const response = await fetch(url, {
    method,
    headers,
    body,
    ...rest,
  });

  if (!response.ok) {
    const text = await response.text().catch(() => '');
    throw new Error(
      `API request failed: ${method} ${url} → ${response.status} ${response.statusText}` +
        (text ? `\n${text}` : ''),
    );
  }

  const contentType = response.headers.get('Content-Type') ?? '';
  const data: T = contentType.includes('application/json')
    ? await response.json()
    : ((await response.text()) as unknown as T);

  return { data, status: response.status, headers: response.headers };
}
