/** Shape of every JSON error body returned by the API. */
interface ApiErrorBody {
  message: string;
  status?: number;
}

/** Thin wrapper around a failed response. */
export class ApiError extends Error {
  constructor(
    public readonly status: number,
    message: string,
  ) {
    super(`API error ${status}: ${message}`);
    this.name = 'ApiError';
  }
}

export interface RequestOptions extends Omit<RequestInit, 'body'> {
  /** Typed request body — will be JSON-serialised automatically. */
  body?: unknown;
}

/**
 * Sends an HTTP request to `path` (relative to VITE_API_BASE_URL), parses the
 * JSON response, and throws an {@link ApiError} for non-2xx status codes.
 *
 * @example
 * const user = await apiFetch<User>('/users/1');
 * const created = await apiFetch<User>('/users', { method: 'POST', body: { name: 'Ada' } });
 */
export async function apiFetch<T>(
  path: string,
  { body, headers, ...rest }: RequestOptions = {},
): Promise<T> {
  const url = `${API_BASE_URL.replace(/\/$/, '')}/${path.replace(/^\//, '')}`;

  const response = await fetch(url, {
    ...rest,
    headers: {
      'Content-Type': 'application/json',
      Accept: 'application/json',
      ...headers,
    },
    // Only serialise body when it is actually provided
    ...(body !== undefined && { body: JSON.stringify(body) }),
  });

  if (!response.ok) {
    // Best-effort: try to extract a message from the response body
    const errorBody: Partial<ApiErrorBody> = await response
      .json()
      .catch(() => ({}));

    throw new ApiError(
      response.status,
      errorBody.message ?? response.statusText,
    );
  }

  // 204 No Content — nothing to parse
  if (response.status === 204) {
    return undefined as T;
  }

  return response.json() as Promise<T>;
}
