 * A thin wrapper around `fetch` that:
 *  - Prepends the API base URL to relative paths
 *  - Defaults Content-Type to application/json for mutating requests
 *  - Throws a typed `ApiError` for non-2xx responses
 *  - Returns parsed JSON (or `undefined` for 204 No Content)
 */
export async function apiFetch<T = unknown>(
  path: string,
  init: ApiRequestInit = {},
): Promise<T> {
  const { method = 'GET', headers: customHeaders, body, ...rest } = init;

  const isMutating = ['POST', 'PUT', 'PATCH'].includes(method);

  const headers = new Headers(customHeaders);
  if (isMutating && !headers.has('Content-Type')) {
    headers.set('Content-Type', 'application/json');
  }

  // Strip a leading slash from path so we never double-slash.
  const url = `${API_BASE_URL}/${path.replace(/^\//, '')}`;

  const response = await fetch(url, { method, headers, body, ...rest });

  if (!response.ok) {
    throw await createApiError(response);
  }

  // 204 No Content — nothing to parse.
  if (response.status === 204) {
    return undefined as T;
  }

  return response.json() as Promise<T>;
}

