/**
 * Builds a full URL from a relative path and optional query params.
 */
function buildUrl(
  path: string,
  params?: RequestOptions['params'],
): string {
  // Allow callers to pass paths with or without a leading slash.
  const url = new URL(
    path.startsWith('/') ? path.slice(1) : path,
    `${API_BASE_URL}/`,
  );

  if (params) {
    for (const [key, value] of Object.entries(params)) {
      if (value !== undefined) {
        url.searchParams.set(key, String(value));
      }
    }
  }

  return url.toString();
