/**
 * API client module
 *
 * Reads configuration from Vite's import.meta.env, which surfaces variables
 * prefixed with VITE_ from your .env files at build time.
 *
 * .env (project root)
 * --------------------
 * VITE_API_BASE_URL=https://api.example.com
 *
 * Restart the dev server after editing .env files.
 */

// ---------------------------------------------------------------------------
// Environment validation
// ---------------------------------------------------------------------------

const apiBaseUrl: string = import.meta.env.VITE_API_BASE_URL;

if (!apiBaseUrl) {
  throw new Error(
    '[api/client] VITE_API_BASE_URL is not set. ' +
      'Add it to your .env file and restart the dev server.',
  );
}

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

/** Subset of fetch options we want callers to control. */
export type ApiRequestInit = Omit<RequestInit, 'body'> & {
  /** Plain objects are serialised to JSON automatically. */
  body?: unknown;
};

export interface ApiResponse<T> {
  data: T;
  status: number;
  headers: Headers;
}

// ---------------------------------------------------------------------------
// Core helper
// ---------------------------------------------------------------------------

/**
 * Thin wrapper around `fetch` that:
 *  - Resolves paths relative to VITE_API_BASE_URL
 *  - Serialises plain-object bodies as JSON
 *  - Throws a descriptive error for non-2xx responses
 *  - Returns a typed { data, status, headers } envelope
 */
export async function apiFetch<T = unknown>(
  path: string,
  { body, headers: extraHeaders, ...rest }: ApiRequestInit = {},
): Promise<ApiResponse<T>> {
  // Ensure the base always ends with a slash so relative resolution is stable.
  const base = apiBaseUrl.endsWith('/') ? apiBaseUrl : `${apiBaseUrl}/`;
  const url = new URL(path.replace(/^\//, ''), base);

  const isJsonBody = body !== undefined && typeof body === 'object';

  const response = await fetch(url.toString(), {
    ...rest,
    headers: {
      Accept: 'application/json',
      ...(isJsonBody && { 'Content-Type': 'application/json' }),
      ...extraHeaders,
    },
    body: isJsonBody ? JSON.stringify(body) : (body as BodyInit | undefined),
  });

  if (!response.ok) {
    const text = await response.text().catch(() => '');
    throw new Error(
      `[api/client] ${rest.method ?? 'GET'} ${url} failed – ` +
        `${response.status} ${response.statusText}` +
        `${text ? `: ${text}` : ''}`,
    );
  }

  // Handle endpoints that return no body (e.g. 204 No Content).
  const contentType = response.headers.get('Content-Type') ?? '';
  const data: T = contentType.includes('application/json')
    ? await response.json()
    : ((await response.text()) as unknown as T);

  return { data, status: response.status, headers: response.headers };
}

