/**
 * Vite exposes env variables prefixed with VITE_ on the import.meta.env object.
 * The variable must be defined in a .env file (or the shell environment) as:
 *
 *   VITE_API_BASE_URL=https://api.example.com
 *
 * Vite performs a static string replacement at build time, so the value is
 * inlined into the bundle – never use this for secrets.
 */

const apiBaseUrl: string = import.meta.env.VITE_API_BASE_URL;

if (!apiBaseUrl) {
  throw new Error(
    '[api] VITE_API_BASE_URL is not defined. ' +
      'Add it to your .env file or CI environment.',
  );
}

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

export type HttpMethod = 'GET' | 'POST' | 'PUT' | 'PATCH' | 'DELETE';

export interface ApiRequestOptions extends Omit<RequestInit, 'method' | 'body'> {
  method?: HttpMethod;
  /** Automatically JSON-serialised and sent with the correct Content-Type. */
  body?: unknown;
  /** Query-string params appended to the path. */
  params?: Record<string, string | number | boolean | undefined>;
}

export interface ApiError extends Error {
  status: number;
  payload: unknown;
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

function buildUrl(
  path: string,
  params?: ApiRequestOptions['params'],
): string {
  // Normalise so callers may pass "/foo" or "foo" interchangeably.
  const base = apiBaseUrl.replace(/\/$/, '');
  const normalised = path.startsWith('/') ? path : `/${path}`;
  const url = new URL(`${base}${normalised}`);

  if (params) {
    for (const [key, value] of Object.entries(params)) {
      if (value !== undefined) {
        url.searchParams.set(key, String(value));
      }
    }
  }

  return url.toString();
}

function createApiError(status: number, payload: unknown): ApiError {
  const message =
    typeof payload === 'object' &&
    payload !== null &&
    'message' in payload &&
    typeof (payload as Record<string, unknown>).message === 'string'
      ? (payload as { message: string }).message
      : `API request failed with status ${status}`;

  const error = new Error(message) as ApiError;
  error.status = status;
  error.payload = payload;
  return error;
}

// ---------------------------------------------------------------------------
// Core fetch helper
// ---------------------------------------------------------------------------

/**
 * Thin wrapper around `fetch` that:
 *  - Prepends the configured API base URL
 *  - Serialises a `body` object to JSON
 *  - Deserialises the JSON response
 *  - Throws a typed `ApiError` for non-2xx responses
 */
export async function apiFetch<TResponse = unknown>(
  path: string,
  options: ApiRequestOptions = {},
): Promise<TResponse> {
  const { method = 'GET', body, params, headers: extraHeaders, ...rest } = options;

  const headers = new Headers(extraHeaders);

  let serialisedBody: string | undefined;
  if (body !== undefined) {
    serialisedBody = JSON.stringify(body);
    headers.set('Content-Type', 'application/json');
  }

  // Forward the Backstage token when running inside a plugin context.
  // (Swap this for your own auth mechanism if needed.)
  const token = sessionStorage.getItem('backstage-token');
  if (token) {
    headers.set('Authorization', `Bearer ${token}`);
  }

  const response = await fetch(buildUrl(path, params), {
    method,
    headers,
    body: serialisedBody,
    ...rest,
  });

  // Parse JSON regardless of status so error bodies can be returned.
  const contentType = response.headers.get('Content-Type') ?? '';
  const payload: unknown = contentType.includes('application/json')
    ? await response.json()
    : await response.text();

  if (!response.ok) {
    throw createApiError(response.status, payload);
  }

  return payload as TResponse;
}

