  if (params) {
    for (const [key, value] of Object.entries(params)) {
      if (value !== undefined) {
        url.searchParams.set(key, String(value));
      }
    }
  }

  return url.toString();
}

function buildInit(options: RequestOptions): RequestInit {
  const { method = 'GET', body, params: _params, ...rest } = options;

  const headers = new Headers(rest.headers);

  let serialisedBody: BodyInit | undefined;

  if (body !== undefined) {
    serialisedBody = JSON.stringify(body);
    // Only set if the caller hasn't provided their own Content-Type.
    if (!headers.has('Content-Type')) {
      headers.set('Content-Type', 'application/json');
    }
  }

  if (!headers.has('Accept')) {
    headers.set('Accept', 'application/json');
  }

  return { ...rest, method, headers, body: serialisedBody };
}

async function parseBody(response: Response): Promise<unknown> {
  const contentType = response.headers.get('Content-Type') ?? '';
  if (contentType.includes('application/json')) {
