// src/module/setupModule.ts

import { createPlugin } from '@backstage/core-plugin-api';

/**
 * Represents the disposable resources created during module setup.
 */
interface ModuleHandle {
  dispose: () => void;
}

let activeHandle: ModuleHandle | undefined;

/**
 * Performs the module's setup logic and returns a handle
 * that can be used to clean up resources on hot reload.
 */
function setup(): ModuleHandle {
  console.log('[setupModule] Running setup...');

  // Example: register a plugin, start a listener, set up subscriptions, etc.
  const plugin = createPlugin({
    id: 'example-plugin',
    routes: {},
  });

  const interval = setInterval(() => {
    console.log('[setupModule] Plugin heartbeat:', plugin.getId());
  }, 5_000);

  const controller = new AbortController();

  // Simulate an async side effect (e.g., an event listener or subscription)
  window.addEventListener(
    'resize',
    () => {
      console.log('[setupModule] Window resized');
    },
    { signal: controller.signal },
  );

  console.log('[setupModule] Setup complete.');

  return {
    dispose() {
      console.log('[setupModule] Disposing previous module instance...');
      clearInterval(interval);
      controller.abort(); // removes the event listener
    },
  };
}

// --- Initial setup on first load ---
activeHandle = setup();

// --- HMR boundary ---
if (import.meta.hot) {
  /**
   * Preserve the active handle across hot reloads so we can
   * dispose it before the new module version runs its setup.
   *
   * `import.meta.hot.data` is Vite's mechanism for passing state
   * from the old module instance to the new one.
   */
  import.meta.hot.accept(() => {
    // This callback runs in the *new* module after it is evaluated.
    // By this point the module-level `setup()` call above has already
    // run, so we only need to clean up the *previous* handle that was
    // stashed in hot.data by the outgoing module.
    const previousHandle = import.meta.hot?.data.handle as
      | ModuleHandle
      | undefined;

    if (previousHandle) {
      previousHandle.dispose();
    }

    // Stash the new handle so the *next* reload can dispose it.
    if (import.meta.hot) {
      import.meta.hot.data.handle = activeHandle;
    }
  });

  /**
   * `vite:beforeUpdate` lets us stash the current handle *before*
   * Vite swaps in the new module, ensuring we always have access to
   * the outgoing instance even if the new module fails to evaluate.
   */
  import.meta.hot.on('vite:beforeUpdate', () => {
    if (import.meta.hot) {
      import.meta.hot.data.handle = activeHandle;
    }
  });
}
