---

### How it works

| Concept | Detail |
|---|---|
| **`import.meta.hot.accept()`** | Declares this module as an **HMR boundary**. Vite will hot-replace it instead of bubbling the update up to the app root. |
| **`import.meta.hot.data`** | A plain object that Vite **persists between reloads** of the same module. It is the idiomatic way to hand state from the old instance to the new one. |
| **`vite:beforeUpdate`** | Fires before the new module is evaluated, giving the outgoing instance a chance to stash its handle safely. |
| **`dispose()`** | Tears down side-effects (intervals, event listeners, subscriptions) so they don't accumulate across reloads. |
| **Dead-code elimination** | The entire `if (import.meta.hot)` block is tree-shaken away in production builds because Vite replaces `import.meta.hot` with `undefined`. |

The lifecycle on each file save is:

1. `vite:beforeUpdate` → stash `activeHandle` into `hot.data`  
2. Vite evaluates the new module → `setup()` runs, `activeHandle` is replaced  
3. `accept` callback → reads `hot.data.handle` (old instance) and calls `dispose()`

Here's a Backstage-style Vite module with HMR support:

```typescript
// src/module/appSetup.ts

import { AppRouter } from '@backstage/core-app-api';
import { createApp } from '@backstage/app-defaults';

interface SetupContext {
  cleanup: () => void;
}

let activeContext: SetupContext | null = null;

function teardown(): void {
  if (activeContext) {
    activeContext.cleanup();
    activeContext = null;
    console.info('[appSetup] Previous setup torn down.');
  }
}

export function setup(): SetupContext {
  console.info('[appSetup] Running setup...');

  // Example: register listeners, initialize services, mount UI, etc.
  const controller = new AbortController();

  const handleVisibilityChange = () => {
    console.info('[appSetup] Visibility changed:', document.visibilityState);
  };

  document.addEventListener('visibilitychange', handleVisibilityChange, {
    signal: controller.signal, // automatically removes listener on abort
  });

  const context: SetupContext = {
    cleanup() {
      controller.abort();
      console.info('[appSetup] Cleanup complete.');
    },
  };

  activeContext = context;
  return context;
}

// ── HMR block ────────────────────────────────────────────────────────────────
// `import.meta.hot` is only defined when Vite's dev server is running.
// Tree-shaking removes this entire block in production builds.

if (import.meta.hot) {
  // Preserve the active context across hot boundary so teardown() can reach it
  // even after the module is re-evaluated.
  import.meta.hot.data.activeContext = activeContext;

  import.meta.hot.accept((newModule) => {
    if (!newModule) {
      // Vite couldn't apply the update; fall back to a full reload.
      console.warn('[appSetup] HMR: module unavailable, forcing full reload.');
      import.meta.hot?.invalidate();
      return;
    }

    console.info('[appSetup] HMR: update received, re-running setup.');

    // Tear down whatever the *previous* evaluation left behind.
    teardown();

    // Re-run setup from the freshly evaluated module.
    newModule.setup();
  });

  import.meta.hot.dispose((data) => {
    // Called just before this module instance is discarded.
    // Stash the live context so the incoming accept() callback can clean it up.
    data.activeContext = activeContext;
    teardown();
  });
}
