### How it works

| HMR hook | Purpose |
|---|---|
| `import.meta.hot.accept(cb)` | Opts this module in as its own HMR boundary. Vite calls `cb` with the freshly evaluated module whenever the file changes. |
| `import.meta.hot.dispose(cb)` | Runs *before* the old module instance is discarded. Ideal for tearing down side-effects (listeners, timers, subscriptions). |
| `import.meta.hot.data` | A plain object that survives across hot swaps, letting `dispose` pass state to the next `accept` handler. |
| `import.meta.hot.invalidate()` | Escalates to a full-page reload when the new module is unexpectedly absent. |

### Key design decisions

1. **`AbortController` for listeners** — passing `{ signal }` to `addEventListener` means a single `controller.abort()` cleans up all listeners registered against that controller, with no bookkeeping array required.
2. **`activeContext` module-level singleton** — keeps the HMR teardown logic simple: always clean up whatever is currently active before running again.
3. **Production safety** — the entire `if (import.meta.hot)` block is statically analysable by Vite/Rollup as dead code when `import.meta.hot` is `undefined`, so it is completely tree-shaken from production bundles.

Here's a Backstage-style Vite module with proper HMR support:

```typescript
// src/module/setupModule.ts

import { AppTheme } from '@backstage/core-plugin-api';

interface ModuleSetupOptions {
  appName: string;
  themes?: AppTheme[];
}

interface ModuleCleanup {
  (): void;
}

let cleanup: ModuleCleanup | undefined;

/**
 * Performs the actual module setup work.
 * Returns a cleanup function to tear down any side effects.
 */
function setup(options: ModuleSetupOptions): ModuleCleanup {
  const { appName, themes = [] } = options;

  console.log(`[setupModule] Setting up "${appName}"...`);

  // Register themes or other side-effectful work here
  const registeredThemes = themes.map(theme => {
    console.log(`[setupModule] Registering theme: ${theme.id}`);
    return theme.id;
  });

  // Example: attach a DOM marker so we can confirm re-runs in the browser
  const marker = document.createElement('meta');
  marker.name = 'app-module-setup';
  marker.content = new Date().toISOString();
  document.head.appendChild(marker);

  console.log(`[setupModule] Setup complete. Themes: ${registeredThemes.join(', ') || 'none'}`);

  // Return a cleanup function that undoes side effects
  return function teardown() {
    console.log(`[setupModule] Tearing down "${appName}"...`);
    document.head.removeChild(marker);
  };
}

/**
 * Public entry point. Runs setup and registers HMR handling.
 */
export function initModule(options: ModuleSetupOptions): void {
  // Run initial setup, storing the returned cleanup handle
  cleanup = setup(options);

  // -------------------------------------------------------------------------
  // HMR block — only active during development (Vite strips this in prod)
  // -------------------------------------------------------------------------
  if (import.meta.hot) {
    /**
     * `accept()` with no arguments (self-accepting) tells Vite that THIS
     * module can handle its own update. When the file changes Vite will
     * re-execute it and then call the callback below.
     */
    import.meta.hot.accept(() => {
      console.log('[setupModule] HMR update received — re-initialising...');

      // 1. Run the previous cleanup so we don't leak side effects
      cleanup?.();

      // 2. Re-run setup with the same options
      cleanup = setup(options);
    });

    /**
     * `dispose` is called just before the old module instance is replaced.
     * Use it to clean up timers, event listeners, subscriptions, etc.
     * The `data` bag persists across the hot swap and can pass state to
     * the incoming module version if needed.
     */
    import.meta.hot.dispose(data => {
      console.log('[setupModule] Disposing old module instance...');
      data.previousOptions = options; // optional: pass data to next version
      cleanup?.();
      cleanup = undefined;
    });
  }
  // -------------------------------------------------------------------------
}
```

