import { AppConfig } from '@backstage/config';

export interface ModuleSetupOptions {
  config: AppConfig;
  rootElement: HTMLElement;
}

let teardownFn: (() => void) | undefined;

export function setupModule(options: ModuleSetupOptions): () => void {
  const { config, rootElement } = options;

  const title = config.getOptionalString('app.title') ?? 'Backstage';

  const container = document.createElement('div');
  container.dataset.moduleId = 'setup-module';
  container.textContent = `Module active: ${title}`;
  rootElement.appendChild(container);

  const interval = setInterval(() => {
    console.log(`[setupModule] heartbeat – ${title}`);
  }, 5_000);

  // Return a teardown function to clean up side-effects
  return function teardown() {
    clearInterval(interval);
    container.remove();
    console.log('[setupModule] torn down');
  };
}
