  // flags toggled at runtime survive a hot reload.
  state.flags = {
    ...resolveDefaultFlags(),
    ...state.flags,
  };

  console.info('[featureFlagsSetup] setup() running', state.flags);

  // Example side-effect: subscribe to a storage event so external tools can
  // flip flags via localStorage.
  const onStorage = (event: StorageEvent) => {
    if (event.key?.startsWith('ff:')) {
      const flag = event.key.slice(3);
      state.flags[flag] = event.newValue === 'true';
      console.info(`[featureFlagsSetup] flag "${flag}" updated`, state.flags);
    }
  };

  window.addEventListener('storage', onStorage);

  // Store cleanup so the HMR dispose handler can release it before the next
  // module instance mounts its own listener.
  state.cleanupFns.push(() => {
    window.removeEventListener('storage', onStorage);
    console.info('[featureFlagsSetup] cleaned up storage listener');
  });

  return {
    isEnabled(flag: string): boolean {
      return state.flags[flag] ?? false;
    },
    getAllFlags(): Record<string, boolean> {
      return { ...state.flags };
    },
