/**
 * Encapsulates all side-effectful setup logic so it can be
 * cleanly torn down and re-run when HMR fires.
 */
function createSetupModule(): SetupModule {
  let intervalId: ReturnType<typeof setInterval> | undefined;

  return {
    initialize() {
      console.info('[SetupModule] Initializing…');

      // Example: register a polling interval
      intervalId = setInterval(() => {
        console.debug('[SetupModule] Polling for updates…');
      }, 5_000);

      // Example: attach a global event listener
      window.addEventListener('online', onNetworkOnline);

      console.info('[SetupModule] Ready.');
    },

    teardown() {
      console.info('[SetupModule] Tearing down…');

      if (intervalId !== undefined) {
        clearInterval(intervalId);
        intervalId = undefined;
      }

      window.removeEventListener('online', onNetworkOnline);

      console.info('[SetupModule] Torn down.');
    },
  };
