function onNetworkOnline() {
  console.info('[SetupModule] Network is back online.');
}

// ─── Bootstrap ───────────────────────────────────────────────────────────────

// Keep a reference to the running instance so HMR can tear it down.
let currentModule: SetupModule | undefined;

function setup() {
  currentModule = createSetupModule();
  currentModule.initialize();
}

setup();

// ─── Hot Module Replacement ───────────────────────────────────────────────────

if (import.meta.hot) {
  /**
   * `accept()` with no arguments (self-acceptance) tells Vite:
   *   "When *this* file changes, swap me in without propagating
   *    the update further up the import graph."
   *
   * The callback receives the fresh module (already evaluated) and
   * is the right place to migrate or re-run state.
   */
  import.meta.hot.accept(() => {
    console.info('[HMR] Module updated — re-running setup.');

    // Tear down the previous instance before the new one starts.
    currentModule?.teardown();

    // Re-run setup with the freshly evaluated module.
    // `setup()` was already called at module evaluation time by the
    // incoming module, so we only need teardown here if we want to
    // control ordering explicitly.  Calling setup() again is safe
    // because the module re-evaluates top-to-bottom on each HMR swap.
  });

  /**
   * `dispose()` runs *before* the old module is discarded.
   * Use it to clean up anything that would otherwise leak
   * (timers, subscriptions, DOM nodes, etc.).
   */
  import.meta.hot.dispose(_data => {
    console.info('[HMR] Disposing old module instance.');
    currentModule?.teardown();
    currentModule = undefined;
  });
