// src/module/setupModule.ts

import { AppRouteBinder } from '@backstage/core-app-api';
import { createPlugin } from '@backstage/core-plugin-api';

/**
 * Internal state that needs to be torn down and re-initialized
 * when the module hot-reloads.
 */
interface ModuleState {
  cleanupFns: Array<() => void>;
  initialized: boolean;
}

let moduleState: ModuleState = {
  cleanupFns: [],
  initialized: false,
};

/**
 * Registers a cleanup function to be called before the module
 * is disposed during an HMR update.
 */
function registerCleanup(fn: () => void): void {
  moduleState.cleanupFns.push(fn);
}

/**
 * Tears down all registered cleanup functions and resets module state.
 */
function teardown(): void {
  console.log('[setupModule] Tearing down module before HMR update…');
  for (const fn of moduleState.cleanupFns) {
    try {
      fn();
    } catch (err) {
      console.error('[setupModule] Error during cleanup:', err);
    }
  }
  moduleState = { cleanupFns: [], initialized: false };
}

/**
 * Core setup logic — simulates wiring up listeners, subscriptions,
 * or plugin bindings that must be re-applied on each HMR cycle.
 */
export function setup(): void {
  if (moduleState.initialized) {
    console.warn('[setupModule] Already initialized; skipping duplicate setup.');
    return;
  }

  console.log('[setupModule] Running setup…');

  // Example: subscribe to some event bus or external resource
  const intervalId = setInterval(() => {
    console.log('[setupModule] Heartbeat tick');
  }, 5_000);

  // Register cleanup so the interval is cleared on HMR dispose
  registerCleanup(() => {
    clearInterval(intervalId);
    console.log('[setupModule] Cleared heartbeat interval');
  });

  // Example: attach a DOM listener
  const handleResize = () => console.log('[setupModule] Window resized');
  window.addEventListener('resize', handleResize);
  registerCleanup(() => {
    window.removeEventListener('resize', handleResize);
    console.log('[setupModule] Removed resize listener');
  });

  moduleState.initialized = true;
  console.log('[setupModule] Setup complete.');
}

// ---------------------------------------------------------------------------
// Hot Module Replacement boundary
// ---------------------------------------------------------------------------
// `import.meta.hot` is injected by Vite only in development mode,
// so the block is naturally tree-shaken away in production builds.
if (import.meta.hot) {
  /**
   * `import.meta.hot.dispose` runs just BEFORE the old module instance
   * is replaced. Use it to clean up any side-effects.
   *
   * The `data` object is passed forward to the incoming module so you
   * can transfer state across the boundary if needed.
   */
  import.meta.hot.dispose((data: Record<string, unknown>) => {
    data.previousState = moduleState; // optional: hand state to the new module
    teardown();
  });

  /**
   * `import.meta.hot.accept` with no arguments (or with this file's own
   * path) tells Vite that THIS module can handle its own updates.
   * The callback receives the new module and re-runs setup automatically.
   */
  import.meta.hot.accept((newModule) => {
    if (!newModule) {
      console.warn('[setupModule] HMR: new module is undefined, skipping re-setup.');
      return;
    }

    // Optionally restore state passed from dispose()
    const previous = import.meta.hot?.data?.previousState as ModuleState | undefined;
    if (previous) {
      console.log('[setupModule] HMR: received previous state', previous);
    }

    // Re-run the exported setup from the freshly loaded module
    (newModule as typeof import('./setupModule')).setup();
    console.log('[setupModule] HMR: module updated successfully.');
  });
}
