```typescript
// src/module/setupModule.ts

import { AppTheme } from '@backstage/core-plugin-api';

interface ModuleConfig {
  name: string;
  version: string;
}

interface ModuleState {
  initialized: boolean;
  config: ModuleConfig;
  cleanupFns: Array<() => void>;
}

let state: ModuleState | undefined;

function cleanup(prevState: ModuleState): void {
  prevState.cleanupFns.forEach(fn => fn());
  prevState.cleanupFns = [];
  prevState.initialized = false;
}

function registerEventListeners(config: ModuleConfig): () => void {
  const handler = (event: Event) => {
    console.log(`[${config.name}] Received event:`, event.type);
  };

  window.addEventListener('resize', handler);

  // Return cleanup function
  return () => {
    window.removeEventListener('resize', handler);
    console.log(`[${config.name}] Event listeners removed`);
  };
}

function registerThemeObserver(theme: AppTheme): () => void {
  const observer = new MutationObserver(mutations => {
    mutations.forEach(mutation => {
      console.log(`[${theme.id}] DOM mutation observed:`, mutation.type);
    });
  });

  observer.observe(document.body, { attributes: true, childList: true });

  return () => {
    observer.disconnect();
    console.log(`[${theme.id}] Observer disconnected`);
  };
}

export function setupModule(config: ModuleConfig): ModuleState {
  if (state?.initialized) {
    console.log(`[${config.name}] Module already initialized, skipping`);
    return state;
  }

  console.log(`[${config.name}] Setting up module v${config.version}`);

  const cleanupFns: Array<() => void> = [];

  cleanupFns.push(registerEventListeners(config));

  const dummyTheme: AppTheme = {
    id: `${config.name}-theme`,
    title: `${config.name} Theme`,
    variant: 'light',
    Provider: ({ children }) => children as React.ReactElement,
  };

  cleanupFns.push(registerThemeObserver(dummyTheme));

  state = {
    initialized: true,
    config,
    cleanupFns,
  };

  console.log(`[${config.name}] Module setup complete`);
  return state;
}

// ---------------------------------------------------------------
// HMR block — only present in development, stripped in production
// ---------------------------------------------------------------
if (import.meta.hot) {
  // Persist state across hot updates so we can clean up properly
  import.meta.hot.data.state = state;

  import.meta.hot.accept((newModule) => {
    if (!newModule) {
      // The update was rejected or the module was deleted
      console.warn('[setupModule] HMR update rejected');
      return;
    }

    console.log('[setupModule] HMR update received, tearing down old module…');

    // Grab the previous state that was stashed in hot.data
    const prevState = import.meta.hot?.data.state as ModuleState | undefined;
    if (prevState?.initialized) {
      cleanup(prevState);
    }

    // Re-run setup with the same config the previous instance used
    if (prevState?.config) {
      console.log('[setupModule] Re-running setup with preserved config');
      newModule.setupModule(prevState.config);
    }
  });

  import.meta.hot.dispose((data) => {
    // Called right before this module is replaced.
    // Stash current state so the accept() callback above can read it.
    console.log('[setupModule] HMR dispose: stashing state for handoff');
    data.state = state;

    if (state?.initialized) {
      cleanup(state);
    }
  });
}
```

### How it works

| HMR hook | Purpose |
|---|---|
| `import.meta.hot.dispose(data => …)` | Runs **before** the old module is torn down. Cleans up side-effects (listeners, observers) and stashes `state` in the persistent `data` bag. |
| `import.meta.hot.accept(newModule => …)` | Runs **after** the new module is evaluated. Reads preserved config from `data`, then calls `setupModule` again so the new code takes effect immediately. |
| `import.meta.hot.data` | A plain object that survives the module swap — the safe way to hand data from the old instance to the new one. |

### Key conventions followed

- **`import.meta.hot` guard** — the entire HMR block is wrapped in the check so

```typescript
