| `import.meta.hot.data` | A plain object Vite keeps alive across swaps. Storing `dispose` here lets the **old** module's `dispose` callback reach the cleanup returned by `setup()`. |
| `import.meta.hot.dispose(cb)` | Vite calls `cb` **before** unloading the current module. We call the stored cleanup so event listeners, timers, etc. are removed before the next version loads. |
| `import.meta.hot.accept(cb)` | Marks this module as *self-accepting*. Vite calls `cb` with the **new** module object, where we re-run `setup()` and store its fresh cleanup handle. |
| `??=` initialisation | Safely seeds `data.dispose` with a no-op on the very first load, avoiding a `null`/`undefined` call if dispose fires before `setup()` has run. |

This replaces the webpack `module.hot` pattern — Vite's `import.meta.hot` is the canonical API per Backstage's ADR.

```typescript
// src/setup.ts

/**
 * Performs any side-effectful setup work for this module — subscribing to
 * services, registering listeners, starting timers, etc.  Returns a cleanup
 * function so that HMR can tear everything down before the next version of
 * the module is applied.
 */
export function setup(): () => void {
  console.log('[setup] initialising module');

  const intervalId = setInterval(() => {
    console.log('[setup] heartbeat');
  }, 5_000);

  window.addEventListener('resize', onResize);

  // Return a dispose / cleanup function.
  return function teardown() {
    console.log('[setup] tearing down previous module instance');
    clearInterval(intervalId);
    window.removeEventListener('resize', onResize);
  };
}

function onResize() {
  console.log('[setup] window resized', window.innerWidth, window.innerHeight);
}

// ---------------------------------------------------------------------------
// Hot Module Replacement (Vite)
// ---------------------------------------------------------------------------
// Guard with `import.meta.hot` so that the HMR block is completely inert
// (and tree-shaken away) in production builds.

if (import.meta.hot) {
  // `import.meta.hot.data` is a plain object that Vite preserves across
  // module swaps — the ideal place to hand the cleanup function between
  // the outgoing and incoming module instances.
  const hot = import.meta.hot;

  // Run initial setup and stash the cleanup so the next swap can call it.
  hot.data.teardown = setup();

  // `accept` with no dependency list means "this module accepts updates to
  // itself".  The callback receives the fresh module instance once Vite has
  // evaluated it.
  hot.accept(() => {
    // Dispose the previous instance before the new one takes over.
    if (typeof hot.data.teardown === 'function') {
      hot.data.teardown();
    }

    // Re-run setup with the freshly evaluated module.
    // Because `accept` re-evaluates this file, `setup` here refers to the
    // updated export from the new module instance passed by Vite.
    hot.data.teardown = setup();
  });

  // `dispose` is called when the module is about to be replaced or the page
  // is about to unload — a last chance to clean up.
  hot.dispose(() => {
    if (typeof hot.data.teardown === 'function') {
      hot.data.teardown();
    }
  });
} else {
  // Cold (production) path — just run setup once with no HMR wiring.
  setup();
}
